-- =====================================================================================
-- Reformulação regulatória 2026-09-16 — Serena (serena)
-- Fragmento PL/pgSQL idempotente, casando por SLUG (nunca UUID), no estilo de
-- supabase/migrations/20260920000000_composicoes_conforme_rotulo.sql.
-- Fonte: docs/conformidade/reformulacao/serena.md e scratchpad/fase2/serena.json.
-- Sem guarda de contagem aqui (a consolidação põe); só o bloco deste produto.
-- NÃO APLICADO em nenhum banco. Veredito esperado: CONFORME CONDICIONADO A (laudo de origem Camellia sinensis da L-teanina nova; laudo vigente de melatonina; laudo novo de cloreto de magnésio; massas do veículo e dos aditivos registradas)
-- =====================================================================================

-- 1. exclusão lógica das composições ativas atuais desta fórmula
update public.formula_compositions fc
set active = false, deleted_at = now(), reason_deleted = 'reformulação regulatória 2026-09-16'
from public.formulas f
where f.id = fc.formula_id and f.deleted_at is null and f.slug = 'serena'
  and fc.deleted_at is null
  and coalesce(fc.metadata->>'fonte', '') <> 'reformulacao_2026-09-16';

-- 2. inserção das composições reformuladas (ingredient_id resolvido por slug; só se ainda não houver linha desta fonte)
insert into public.formula_compositions (formula_id, ingredient_name, quantity, unit, sort_order, ingredient_id, metadata)
select f.id, v.ingredient_name, v.quantity, v.unit::public.composition_unit, v.sort_order, i.id, v.metadata::jsonb
from (values
    ('serena', 0, 'Magnésio (cloreto de magnésio)', 70, 'mg', 'magnesio', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Magnésio", "forma_insumo": "Cloreto de magnésio, anidro (CAS 7786-30-3)", "massa_insumo_mg": 275.8518, "laudo_lote": "950301 (Analitic, fabricante 23110901)", "laudo_validade": "08/11/2026", "laudo_vencido": false, "teor_pct": 25.38, "teor_fonte": "laudo", "ativo_mg": 70, "unidade_ativo": "mg", "minimo": 63, "maximo": 350, "pct_do_maximo": 20.0, "linha_anexo": "I·Cloreto de magnésio; III/IV·Magnésio", "status": "dose ajustada", "e_sal": false, "observacao": "63 mg era o mínimo exato — o próprio memorial recomenda 70 mg (111% do mínimo; 20% do teto). Com o teor do laudo aplicado (25,38%), os 246,77 mg do memorial entregariam 62,6 mg, abaixo do mínimo: a massa sobe para 275,8 mg. Laudo vence em 08/11/2026 — pedir novo."}'),
    ('serena', 1, 'L-teanina de folhas de Camellia sinensis', 60, 'mg', 'l-teanina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Teanina", "forma_insumo": "L-teanina de folhas de Camellia sinensis — insumo a adquirir (rota B)", "massa_insumo_mg": 60.0, "laudo_lote": "AUTO039250 (Lepuge, fabricante 202408145) — SÍNTESE QUÍMICA, não serve", "laudo_validade": "13/08/2027", "laudo_vencido": false, "teor_pct": 100.0, "teor_fonte": "assumido", "ativo_mg": 60, "unidade_ativo": "mg", "minimo": 50, "maximo": 250, "pct_do_maximo": 24.0, "linha_anexo": "I·L-teanina de folhas de Camellia sinensis (IN 318/2024); III·Teanina 50 mg; IV·250 mg", "status": "forma trocada (origem) + dose ajustada — PENDENTE laudo", "e_sal": false, "observacao": "50 mg era o mínimo exato; 60 mg = 120% do mínimo (24% do teto), como o memorial rev02 recomenda. Origem: só a de folhas de Camellia sinensis é autorizada; a fábrica registra que o fornecedor atual (INLAB) não comercializa L-teanina — comprar de distribuidor com especificação Blue California. Rota A (retirar) na seção 8."}'),
    ('serena', 2, 'Mio-inositol', 50, 'mg', 'inositol', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Inositol", "forma_insumo": "Inositol (Mio-inositol/Meso-inositol) (CAS 87-89-8)", "massa_insumo_mg": 50.0701, "laudo_lote": "950479 (memorial rev02; digitalização, não relida). Alternativa em texto: IDNLABS YW20241103, 99,61%, val. 11/2028", "laudo_validade": "não relida", "laudo_vencido": null, "teor_pct": 99.86, "teor_fonte": "memorial", "ativo_mg": 50, "unidade_ativo": "mg", "minimo": null, "maximo": 2000, "pct_do_maximo": 2.5, "linha_anexo": "I·Inositol (Mio-inositol/Meso-inositol) (IN 76/2020); III·NE; IV·2 g", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (2,5% do teto)."}'),
    ('serena', 3, 'Vitamina B6 (cloridrato de piridoxina)', 1.3, 'mg', 'vitamina-b6', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina B6", "forma_insumo": "Cloridrato de piridoxina (CAS 58-56-0)", "massa_insumo_mg": 1.5817, "laudo_lote": "91188 (Analitic, fabricante 241229T092)", "laudo_validade": "28/12/2027", "laudo_vencido": false, "teor_pct": 99.9, "teor_fonte": "laudo", "ativo_mg": 1.3, "unidade_ativo": "mg", "minimo": 0.26, "maximo": 98.6, "pct_do_maximo": 1.32, "linha_anexo": "I·Cloridrato de piridoxina; III/IV·Vitamina B6", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (1,3% do teto)."}'),
    ('serena', 4, 'Melatonina', 0.18, 'mg', 'melatonina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Melatonina", "forma_insumo": "Melatonina (CAS 73-31-4)", "massa_insumo_mg": 0.1812, "laudo_lote": "950151 (Analitic, fabricante MCS211210) — os 5 laudos de melatonina da máquina estão vencidos", "laudo_validade": "09/12/2024", "laudo_vencido": true, "teor_pct": 99.33, "teor_fonte": "laudo vencido", "ativo_mg": 0.18, "unidade_ativo": "mg", "minimo": null, "maximo": 0.21, "pct_do_maximo": 85.71, "linha_anexo": "I·Melatonina (IN 102/2021); III·NE; IV·0,21 mg", "status": "dose ajustada — PENDENTE laudo", "e_sal": false, "observacao": "0,21 mg era o teto exato; nova dose 0,18 mg (85,7% do teto). O memorial recomenda 0,19 (90,5%); 0,18 fica dentro da regra de ≤ 90%. O laudo em uso é o mais antigo da linha (lote de dezembro de 2021) e venceu há 21 meses — laudo do lote em uso obrigatório."}')
) as v(slug, sort_order, ingredient_name, quantity, unit, ingredient_slug, metadata)
join public.formulas f on f.slug = v.slug and f.deleted_at is null
join public.ingredients i on i.slug = v.ingredient_slug and i.deleted_at is null
where not exists (
    select 1 from public.formula_compositions x
    where x.formula_id = f.id and x.deleted_at is null and x.metadata->>'fonte' = 'reformulacao_2026-09-16'
);

